    const T = cell - 1
    const paths = {}
    const tx = {}
    const put = (k, x, y, g) => {
      const e = (tx[k] ||= { x: [], y: [], g: '' })
      e.x.push(n(x))
      e.y.push(n(y))
      e.g += g
    }
